Edge graph[MAXN][MAXM];
int graph_size[MAXN];
int level[MAXN];
int iter[MAXN];
int n, m, s, t;

int min_int(int a, int b) { return a < b ? a : b; }

void add_edge(int from, int to, int cap) {
    graph[from][graph_size[from]].to = to;
    graph[from][graph_size[from]].rev = graph_size[to];
    graph[from][graph_size[from]].cap = cap;
    graph_size[from]++;

    graph[to][graph_size[to]].to = from;
    graph[to][graph_size[to]].rev = graph_size[from] - 1;
    graph[to][graph_size[to]].cap = 0; // reverse edge initially 0
    graph_size[to]++;
}

void bfs() {
    memset(level, -1, sizeof(level));
    int queue[MAXN], front = 0, back = 0;
    level[s] = 0;
    queue[back++] = s;
    while (front < back) {
        int v = queue[front++];
        for (int i = 0; i < graph_size[v]; i++) {
            Edge &e = graph[v][i];
            if (e.cap > 0 && level[e.to] < 0) {
                level[e.to] = level[v] + 1;
                queue[back++] = e.to;
            }
        }
    }
}

int dfs(int v, int f) {
    if (v == t) return f;
    for (int &i = iter[v]; i < graph_size[v]; i++) {
        Edge &e = graph[v][i];
        if (e.cap > 0 && level[v] < level[e.to]) {
            int d = dfs(e.to, min_int(f, e.cap));
            if (d > 0) {
                e.cap -= d;
                graph[e.to][e.rev].cap += d;
                return d;
            }
        }
    }
    return 0;
}

int max_flow() {
    int flow = 0;
    while (1) {
        bfs();
        if (level[t] < 0) return flow;
        memset(iter, 0, sizeof(iter));
        int f;
        while ((f = dfs(s, INF)) > 0) {
            flow += f;
        }
    }
}

