typedef long long ll;

typedef struct {
    int to, rev;
    ll cap;
    int id;
    int cost; /* 0 if keep direction, 1 if reversed road */
} Edge;

typedef struct {
    Edge *e;
    int sz, cap;
} Vec;

static void vec_push(Vec *v, Edge x) {
    if (v->sz == v->cap) {
        v->cap = v->cap ? v->cap * 2 : 4;
        v->e = (Edge*)realloc(v->e, v->cap * sizeof(Edge));
    }
    v->e[v->sz++] = x;
}

static void add_edge(Vec *g, int u, int v, ll cap, int id, int cost) {
    Edge a = {v, g[v].sz, cap, id, cost};
    Edge b = {u, g[u].sz, 0,  id, cost};
    vec_push(&g[u], a);
    vec_push(&g[v], b);
}

/* Dinic */
static int *level_, *it_;
static int N_;

static int bfs(Vec *g, int s, int t) {
    int *q = (int*)malloc(N_ * sizeof(int));
    for (int i = 0; i < N_; i++) level_[i] = -1;
    int head = 0, tail = 0;
    level_[s] = 0;
    q[tail++] = s;
    while (head < tail) {
        int v = q[head++];
        for (int i = 0; i < g[v].sz; i++) {
            Edge *e = &g[v].e[i];
            if (e->cap > 0 && level_[e->to] < 0) {
                level_[e->to] = level_[v] + 1;
                q[tail++] = e->to;
            }
        }
    }
    int ok = level_[t] >= 0;
    free(q);
    return ok;
}

static ll dfs(Vec *g, int v, int t, ll f) {
    if (v == t) return f;
    for (int *i = &it_[v]; *i < g[v].sz; (*i)++) {
        Edge *e = &g[v].e[*i];
        if (e->cap <= 0 || level_[v] + 1 != level_[e->to]) continue;
        ll ret = dfs(g, e->to, t, f < e->cap ? f : e->cap);
        if (ret > 0) {
            e->cap -= ret;
            g[e->to].e[e->rev].cap += ret;
            return ret;
        }
    }
    return 0;
}

static ll dinic(Vec *g, int n, int s, int t) {
    N_ = n;
    level_ = (int*)malloc(n * sizeof(int));
    it_ = (int*)malloc(n * sizeof(int));
    ll flow = 0, inf = (ll)4e18;
    while (bfs(g, s, t)) {
        for (int i = 0; i < n; i++) it_[i] = 0;
        while (1) {
            ll f = dfs(g, s, t, inf);
            if (!f) break;
            flow += f;
        }
    }
    free(level_);
    free(it_);
    return flow;
}

/* Min-cost max-flow using SPFA */
typedef struct {
    int v, ei;
} Prev;

static ll min_cost_max_flow(Vec *g, int n, int s, int t, ll targetFlow, int *usedReversed) {
    ll flow = 0, cost = 0;
    ll *dist = (ll*)malloc(n * sizeof(ll));
    int *inQ = (int*)malloc(n * sizeof(int));
    Prev *pr = (Prev*)malloc(n * sizeof(Prev));
    int *q = (int*)malloc((n * 4 + 10) * sizeof(int));

    while (flow < targetFlow) {
        for (int i = 0; i < n; i++) {
            dist[i] = (ll)4e18;
            inQ[i] = 0;
            pr[i].v = -1;
            pr[i].ei = -1;
        }
        int head = 0, tail = 0, qcap = n * 4 + 10;
        dist[s] = 0;
        q[tail++] = s;
        inQ[s] = 1;

        while (head != tail) {
            int v = q[head++];
            if (head == qcap) head = 0;
            inQ[v] = 0;
            for (int i = 0; i < g[v].sz; i++) {
                Edge *e = &g[v].e[i];
                if (e->cap <= 0) continue;
                int to = e->to;
                ll nd = dist[v] + e->cost;
                if (nd < dist[to]) {
                    dist[to] = nd;
                    pr[to].v = v;
                    pr[to].ei = i;
                    if (!inQ[to]) {
                        q[tail++] = to;
                        if (tail == qcap) tail = 0;
                        inQ[to] = 1;
                    }
                }
            }
        }

        if (dist[t] >= (ll)4e18 / 2) break;

        ll add = targetFlow - flow;
        int v = t;
        while (v != s) {
            int pv = pr[v].v, ei = pr[v].ei;
            if (pv < 0) { add = 0; break; }
            if (g[pv].e[ei].cap < add) add = g[pv].e[ei].cap;
            v = pv;
        }
        if (add == 0) break;

        v = t;
        while (v != s) {
            int pv = pr[v].v, ei = pr[v].ei;
            Edge *e = &g[pv].e[ei];
            e->cap -= add;
            g[v].e[e->rev].cap += add;
            v = pv;
        }

        flow += add;
        cost += add * dist[t];
    }

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < g[i].sz; j++) {
            Edge *e = &g[i].e[j];
            if (e->id >= 0 && e->cost == 1) {
                /* reverse edge used iff residual reverse cap > 0, i.e. some flow passed */
                if (g[e->to].e[e->rev].cap > 0) usedReversed[e->id] = 1;
            }
        }
    }

    free(dist);
    free(inQ);
    free(pr);
    free(q);
    return cost;
}

