#include <bits/stdc++.h>
using namespace std;

/*
We model each original directed road u -> v with capacity c as:
- forward edge u -> v with capacity c and cost 0
- reverse-using edge v -> u with capacity c and cost 1

Then we want to send the maximum possible flow from S to T while minimizing
the number of reversed roads used (counted with multiplicity of flow units).
This is a standard min-cost max-flow on the transformed network.

To output which original roads were reversed, we report those roads whose
reverse-using edge carries positive flow in the final solution.

If the intended statement means "list roads reversed" regardless of how much
flow uses them, this matches naturally.

Input format assumed:
N M S T
u1 v1 c1
...
uM vM cM

Output:
maximum_flow number_of_reversed_roads
list of reversed road indices (1-based), one per line or space-separated

Since the original statement fragment does not specify exact output format,
we use:
maxflow
k
i1 i2 ... ik

If k=0, the third line is empty.
*/

struct Edge {
    int to, rev;
    long long cap, cost;
};

struct MinCostMaxFlow {
    int n;
    vector<vector<Edge>> g;
    MinCostMaxFlow(int n) : n(n), g(n) {}

    int addEdge(int s, int t, long long cap, long long cost) {
        Edge a{t, (int)g[t].size(), cap, cost};
        Edge b{s, (int)g[s].size(), 0, -cost};
        g[s].push_back(a);
        g[t].push_back(b);
        return (int)g[s].size() - 1;
    }

    pair<long long,long long> minCostMaxFlow(int s, int t) {
        const long long INF = (1LL<<62);
        long long flow = 0, cost = 0;
        vector<long long> dist(n), pot(n, 0);
        vector<int> pv(n), pe(n);

        while (true) {
            fill(dist.begin(), dist.end(), INF);
            dist[s] = 0;
            priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<pair<long long,int>>> pq;
            pq.push({0, s});

            while (!pq.empty()) {
                auto [d, v] = pq.top();
                pq.pop();
                if (d != dist[v]) continue;
                for (int i = 0; i < (int)g[v].size(); ++i) {
                    Edge &e = g[v][i];
                    if (e.cap <= 0) continue;
                    long long nd = d + e.cost + pot[v] - pot[e.to];
                    if (nd < dist[e.to]) {
                        dist[e.to] = nd;
                        pv[e.to] = v;
                        pe[e.to] = i;
                        pq.push({nd, e.to});
                    }
                }
            }

            if (dist[t] == INF) break;

            for (int i = 0; i < n; ++i)
                if (dist[i] < INF) pot[i] += dist[i];

            long long add = INF;
            for (int v = t; v != s; v = pv[v]) {
                add = min(add, g[pv[v]][pe[v]].cap);
            }

            for (int v = t; v != s; v = pv[v]) {
                Edge &e = g[pv[v]][pe[v]];
                e.cap -= add;
                g[v][e.rev].cap += add;
                cost += add * e.cost;
            }
            flow += add;
        }
        return {flow, cost};
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M, S, T;
    if (!(cin >> N >> M >> S >> T)) return 0;
    --S; --T;

    MinCostMaxFlow mcmf(N);

