    vector<int> reversed;
    for (int i = 0; i < M; ++i) {
        auto &r = roads[i];
        // reverse edge original residual capacity is stored in g[revUseFrom][revUseIndex]
        // If some flow x used it, residual cap became c-x, and reverse residual became x.
        long long remaining = mcmf.g[r.revUseFrom][r.revUseIndex].cap;
        if (remaining < r.c) reversed.push_back(i + 1);
    }

    cout << maxflow << '\n';
    cout << reversed.size() << '\n';
    for (int i = 0; i < (int)reversed.size(); ++i) {
        if (i) cout << ' ';
        cout << reversed[i];
    }
    cout << '\n';

    return 0;
}

