public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return Long.MIN_VALUE;
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Edge {
        int to, rev;
        long cap, cost, flow;

        Edge(int to, int rev, long cap, long cost) {
            this.to = to;
            this.rev = rev;
            this.cap = cap;
            this.cost = cost;
            this.flow = 0;
        }
    }

    static class MinCostMaxFlow {
        int n;
        ArrayList<Edge>[] g;

        @SuppressWarnings("unchecked")
        MinCostMaxFlow(int n) {
            this.n = n;
            g = new ArrayList[n];
            for (int i = 0; i < n; i++) g[i] = new ArrayList<>();
        }

        int addEdge(int s, int t, long cap, long cost) {
            Edge a = new Edge(t, g[t].size(), cap, cost);
            Edge b = new Edge(s, g[s].size(), 0, -cost);
            g[s].add(a);
            g[t].add(b);
            return g[s].size() - 1;
        }

        long[] minCostMaxFlow(int s, int t) {
            long flow = 0;
            long cost = 0;

            long[] pot = new long[n];
            long INF = Long.MAX_VALUE / 4;

            while (true) {
                long[] dist = new long[n];
                Arrays.fill(dist, INF);
                dist[s] = 0;

                int[] pv = new int[n];
                int[] pe = new int[n];
                Arrays.fill(pv, -1);

                PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
                pq.add(new long[]{0, s});

                while (!pq.isEmpty()) {
                    long[] cur = pq.poll();
                    long d = cur[0];
                    int v = (int) cur[1];
                    if (d != dist[v]) continue;

                    for (int i = 0; i < g[v].size(); i++) {
                        Edge e = g[v].get(i);
                        if (e.cap <= 0) continue;
                        long nd = d + e.cost + pot[v] - pot[e.to];
                        if (nd < dist[e.to]) {
                            dist[e.to] = nd;
                            pv[e.to] = v;
                            pe[e.to] = i;
                            pq.add(new long[]{nd, e.to});
                        }
                    }
                }

                if (pv[t] == -1) break;

                for (int i = 0; i < n; i++) {
                    if (dist[i] < INF) pot[i] += dist[i];
                }

                long add = INF;
                for (int v = t; v != s; v = pv[v]) {
                    Edge e = g[pv[v]].get(pe[v]);
                    add = Math.min(add, e.cap);
                }

                for (int v = t; v != s; v = pv[v]) {
                    Edge e = g[pv[v]].get(pe[v]);
                    Edge r = g[e.to].get(e.rev);
                    e.cap -= add;
                    r.cap += add;
                    e.flow += add;
                    r.flow -= add;
                    cost += add * e.cost;
                }

                flow += add;
            }

            return new long[]{flow, cost};
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int n = fs.nextInt();
        if (n == Integer.MIN_VALUE) return;
        int m = fs.nextInt();
        int s = fs.nextInt() - 1;
        int t = fs.nextInt() - 1;

        MinCostMaxFlow mf = new MinCostMaxFlow(n);

        int[] revFrom = new int[m];
        int[] revEdgeIndex = new int[m];

        for (int i = 0; i < m; i++) {
            int u = fs.nextInt() - 1;
            int v = fs.nextInt() - 1;
            long c = fs.nextLong();

            mf.addEdge(u, v, c, 0);
            revFrom[i] = v;
            revEdgeIndex[i] = mf.addEdge(v, u, c, 1);
        }

        long[] ans = mf.minCostMaxFlow(s, t);
        long maxFlow = ans[0];

        ArrayList<Integer> reversed = new ArrayList<>();
        for (int i = 0; i < m; i++) {
            Edge e = mf.g[revFrom[i]].get(revEdgeIndex[i]);
            if (e.flow > 0) reversed.add(i + 1);
        }

        StringBuilder out = new StringBuilder();
        out.append(maxFlow).append('\n');
        out.append(reversed.size()).append('\n');
        for (int i = 0; i < reversed.size(); i++) {
            if (i > 0) out.append(' ');
            out.append(reversed.get(i));
        }
        out.append('\n');

        System.out.print(out.toString());
    }
